ROOT=Path('/home/jwk/agent')
OLD=ROOT/'builds/fc-native-pmem-v1'
SOURCE=OLD/'stage/fc-source'
DEST=ROOT/'builds/fc-gnu-integrated-v1'
RUST=ROOT/'toolchains/agentenv-rust-1.99.0/rustup/toolchains/1.99.0-aarch64-unknown-linux-gnu/bin'
OLD_FC_SHA='ce17c76b9a62656f455138624781ca1e583eeb059658101840a51f257cb6f01d'
POLICY_BPF_SHA='afa4de05b17b89dec5c9a8f03b4852f836b45b28c76f6bdde812bd84ede2af00'

def need(ok,reason):
    if not ok:raise RuntimeError(reason)

def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(1024**2),b''):h.update(block)
    return h.hexdigest()

def build_policy_output(messages,target):
    paths=set()
    for line in messages.splitlines():
        try:row=json.loads(line)
        except ValueError:continue
        if row.get('reason')=='build-script-executed' and row.get('out_dir'):
            directory=Path(row['out_dir'])
            if directory.parent.name.startswith('firecracker-'):paths.add(directory/'seccomp_filter.bpf')
    need(len(paths)==1,'Expected one actual FC build-script output')
    path=paths.pop();need(path.resolve(strict=True)==path and path.is_relative_to(target),'Unexpected policy output location')
    need(path.stat().st_size==2810 and sha(path)==POLICY_BPF_SHA,'Embedded build policy differs from the validated external policy')
    return path

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--run',action='store_true');args=parser.parse_args()
    if not args.run:
        print(json.dumps({'status':'PLAN_ONLY','newBuildDirectory':str(DEST),'SDK_called':False,'services_changed':False,'oldBinaryOverwritten':False},indent=2));return 0
    need(sys.platform=='linux' and os.uname().machine=='aarch64' and os.uname().nodename=='server1','Use A ARM64')
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk')
    need(SOURCE.resolve(strict=True)==SOURCE and not DEST.exists() and DEST.resolve()==DEST,'Existing build preserved; do not retry blindly')
    need(shutil.disk_usage(OLD).free>=4*1024**3,'Need 4GiB free disk for isolated source and incremental build')
    for name,pin in INPUT_PINS.items():
        path=SOURCE/name;need(path.resolve(strict=True)==path and sha(path)==pin,'Reviewed old source differs: '+name)
    previous=OLD/'stage/artifacts/firecracker';need(sha(previous)==OLD_FC_SHA,'Previous staged FC changed')
    helper=ROOT/'A_futex265_policy_guest_v5.py'
    need(sha(helper)=='d88bdc1f2578bb5f367030e1ca7352c098016a223f6259aff2399168d067563b','Reviewed launcher packet changed')
    config_path=ROOT/'r/pm-a-v1/native-session/futex-v5/guest-config.json'
    need(sha(config_path)=='dec3626e97b51bea9d8085abb3bff3f2c7322a94deb084e09cad7ae74671461c','Prior passing configuration changed')
    gate=json.loads((ROOT/'r/pm-a-v1/guest-futex-v5/return.json').read_text())
    need(gate.get('guestDaxSelftestPassed') is True and gate.get('firecrackerExit')==0 and gate.get('safeToRetireThisLease') is True,'Completed external-filter DAX pass required')
    os.umask(0o077);DEST.mkdir(mode=0o700)
    report={'status':'BUILDING_STRICT_BUILTIN_POLICY','SDK_called':False,'Guest_created':False,'services_changed':False,'oldBinaryOverwritten':False}
    try:
        for path in SOURCE.rglob('*'):need(not path.is_symlink(),'Unexpected source symlink; preserve new build')
        source=DEST/'source';shutil.copytree(SOURCE,source,ignore=shutil.ignore_patterns('.git','target'))
        for name,text in PAYLOAD.items():(source/name).write_bytes(text.encode())
        target=OLD/'stage/fc-target';private=OLD/'stage/private-lib'
        need((private/'libseccomp.so').is_file(),'Existing reviewed private link library missing')
        env=dict(os.environ)
        for key in ('RUSTFLAGS','CARGO_ENCODED_RUSTFLAGS','RUSTC_WRAPPER','RUSTC_WORKSPACE_WRAPPER','LD_PRELOAD','LD_AUDIT'):env.pop(key,None)
        env.update(PATH=str(RUST)+os.pathsep+env['PATH'],RUSTC=str(RUST/'rustc'),RUSTDOC=str(RUST/'rustdoc'),
            CARGO_HOME=str(OLD/'cargo-home'),CARGO_TARGET_DIR=str(target),CARGO_NET_OFFLINE='true',
            CARGO_PROFILE_RELEASE_LTO='false',CARGO_PROFILE_RELEASE_DEBUG='0',CARGO_BUILD_JOBS='2',
            LIBRARY_PATH=str(private),LD_LIBRARY_PATH=str(private))
        command=[str(RUST/'cargo'),'build','--release','--frozen','--offline','--manifest-path',str(source/'Cargo.toml'),
                 '--target','aarch64-unknown-linux-gnu','-p','firecracker','--bin','firecracker','--message-format=json-render-diagnostics']
        started=time.monotonic();print('PHASE=offline_FC_build_with_strict_embedded_GNU_policy',flush=True)
        with (DEST/'build.log').open('xb') as log:
            process=subprocess.Popen(command,cwd=source,env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
            try:
                while True:
                    try:code=process.wait(timeout=30);break
                    except subprocess.TimeoutExpired:
                        print('BUILD_PROGRESS elapsed_s='+str(int(time.monotonic()-started)),flush=True)
                        need(time.monotonic()-started<1200,'Build exceeded its 20-minute budget')
            except BaseException:
                if process.poll() is None:
                    os.killpg(process.pid,signal.SIGTERM)
                    try:process.wait(timeout=10)
                    except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=10)
                raise
        need(code==0,'FC build failed; preserve build.log')
        log=DEST/'build.log';need(log.stat().st_size<=32*1024**2,'Build output exceeds parsing budget')
        policy=build_policy_output(log.read_text(errors='replace'),target)
        binary=target/'aarch64-unknown-linux-gnu/release/firecracker'
        raw=binary.read_bytes();need(raw[:4]==b'\x7fELF' and int.from_bytes(raw[18:20],'little')==183,'Expected AArch64 ELF')
        need(policy.read_bytes() in raw,'Built binary does not contain its validated embedded policy')
        artifacts=DEST/'artifacts';artifacts.mkdir(mode=0o700)
        fc=artifacts/'firecracker';shutil.copy2(binary,fc)
        need(sha(fc)==sha(binary) and sha(previous)==OLD_FC_SHA,'New copy differs or prior staged FC changed')
        for name,pin in INPUT_PINS.items():need(sha(SOURCE/name)==pin,'Old source changed during build')
        version=subprocess.run([str(fc),'--version'],capture_output=True,text=True,timeout=10,env=env)
        need(version.returncode==0,'New FC cannot load')
        helper_module=runpy.run_path(str(helper))
        launcher=DEST/'builtin-guest.py'
        launcher.write_bytes(helper_module['PAYLOAD']['native_pmem_guest_policy_trace.py'].replace('native-pmem-guest-futex-v5','native-pmem-builtin-policy-v1').encode())
        config=json.loads(config_path.read_text());config.pop('seccompFilter',None);config.pop('traceRunner',None)
        config['firecracker']={'path':str(fc),'sha256':sha(fc),'bytes':fc.stat().st_size}
        new_config=DEST/'guest-config.json';new_config.write_text(json.dumps(config,indent=2))
        output=ROOT/'r/pm-a-v1/guest-builtin-policy-v1'
        unit=types.ModuleType('reviewed_unit');exec(helper_module['PAYLOAD']['native_guest_unit_v2.py'],unit.__dict__)
        block=unit.root_block('node-a',launcher,sha(launcher),new_config,sha(new_config),output,'v6')
        (DEST/'root-review.txt').write_text(block)
        report.update(status='FC_BUILT_WITH_MATCHING_EMBEDDED_POLICY_NOT_DEPLOYED',
            firecracker=config['firecracker'],embeddedPolicySha256=sha(policy),embeddedPolicyBytes=2810,
            externalFilterRequired=False,priorStagedBinaryUnchanged=True,priorSourceUnchanged=True,
            guestConfig=str(new_config),guestOutput=str(output),elapsedSeconds=round(time.monotonic()-started,2))
        print('BEGIN_BUILTIN_POLICY_BUILD_REPORT\n'+json.dumps(report,indent=2)+'\nEND_BUILTIN_POLICY_BUILD_REPORT',flush=True)
        print('BEGIN_BUILTIN_POLICY_GUEST_ROOT\n'+block+'END_BUILTIN_POLICY_GUEST_ROOT',flush=True)
        return 0
    except Exception as error:
        report.update(status='STOPPED_BUILTIN_POLICY_BUILD',reason=str(error)[:1000],errorType=type(error).__name__)
        print(json.dumps(report,indent=2),flush=True);return 1
    finally:
        (DEST/'return.json').write_text(json.dumps(report,indent=2))

if __name__=='__main__':raise SystemExit(main())
